<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$editing=!empty($manual['id']);$sectionRows=$sections?:array_fill(0,6,['heading'=>'','content'=>'']);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$editing?'Edit':'Add'?> Program Manual</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1000px;margin:auto;padding:1rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}label{display:block;font-weight:700}input,select,textarea{width:100%;box-sizing:border-box}.section,fieldset{padding:1rem;margin:1rem 0;border:1px solid #ccd3da;border-radius:8px}.errors{color:#a51d2d}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main><h1><?=$editing?'Edit':'Add'?> Program Manual</h1><?php if($errors):?><div class="errors" role="alert"><ul><?php foreach($errors as$e):?><li><?=$h($e)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" enctype="multipart/form-data"><?=csrfField()?><div class="grid"><p><label>Program<select name="program_specification_id" required><option value="">Select</option><?php foreach($programs as$p):?><option value="<?=(int)$p['id']?>" <?=((int)($manual['program_specification_id']??0)===(int)$p['id'])?'selected':''?>><?=$h($p['program_name'].' '.$p['program_code'])?></option><?php endforeach;?></select></label></p><p><label>Manual title<input name="title" required maxlength="255" value="<?=$h($manual['title']??'')?>"></label></p><p><label>Version<input name="version_label" required maxlength="100" value="<?=$h($manual['version_label']??'')?>"></label></p><p><label>Academic period<input name="academic_period" maxlength="50" value="<?=$h($manual['academic_period']??'')?>"></label></p><p><label>Status<select name="status"><?php foreach(['Draft','Under Review','Approved','Archived']as$s):?><option <?=($manual['status']??'Draft')===$s?'selected':''?>><?=$h($s)?></option><?php endforeach;?></select></label></p><p><label>Prepared by<input name="prepared_by" value="<?=$h($manual['prepared_by']??'')?>"></label></p><p><label>Approved by<input name="approved_by" value="<?=$h($manual['approved_by']??'')?>"></label></p><p><label>Updated date<input type="date" name="updated_date" value="<?=$h($manual['updated_date']??'')?>"></label></p><p><label>Approval date<input type="date" name="approval_date" value="<?=$h($manual['approval_date']??'')?>"></label></p><p><label>Next review date<input type="date" name="next_review_date" value="<?=$h($manual['next_review_date']??'')?>"></label></p></div><fieldset><legend>Declared facts from this manual</legend><div class="grid"><p><label>Program name in manual<input name="declared_program_name" value="<?=$h($manual['declared_program_name']??'')?>"></label></p><p><label>Credit hours<input type="number" min="0" name="declared_credit_hours" value="<?=$h($manual['declared_credit_hours']??'')?>"></label></p><p><label>Semesters<input type="number" min="0" name="declared_semesters" value="<?=$h($manual['declared_semesters']??'')?>"></label></p><p><label>PLO count<input type="number" min="0" name="declared_plo_count" value="<?=$h($manual['declared_plo_count']??'')?>"></label></p><p><label>Curriculum row count<input type="number" min="0" name="declared_course_count" value="<?=$h($manual['declared_course_count']??'')?>"></label></p><?php if($editing):?><p><label>Supersedes<select name="supersedes_manual_id"><option value="">None</option><?php foreach($revisions as$r):if((int)$r['id']===(int)$manual['id'])continue;?><option value="<?=(int)$r['id']?>" <?=((int)($manual['supersedes_manual_id']??0)===(int)$r['id'])?'selected':''?>><?=$h($r['version_label'].' - '.$r['title'])?></option><?php endforeach;?></select></label></p><?php endif;?></div></fieldset><p><label>Source PDF <?=$editing?'(leave blank to retain current file)':''?><input type="file" name="source_pdf" accept="application/pdf,.pdf" <?=$editing?'':'required'?>></label></p><h2>Structured sections</h2><p>Use any headings appropriate to this program; the structure is not tied to Health Promotion.</p><?php foreach($sectionRows as$x):?><div class="section"><label>Heading<input name="section_heading[]" value="<?=$h($x['heading']??'')?>"></label><label>Summary/content<textarea name="section_content[]" rows="5"><?=$h($x['content']??'')?></textarea></label></div><?php endforeach;?><button type="submit">Save program manual</button></form></main></body></html>
